describe('Browser Push Notifications', () => {
    beforeEach(() => {
        cy.visit('/'); // Visit the application home page
        cy.request('POST', '/api/notifications/subscribe', { userId: 'testUser' }); // Subscribe to notifications
    });

    it('should display a push notification for urgent alerts', () => {
        cy.intercept('POST', '/api/notifications/send', {
            statusCode: 200,
            body: { message: 'Urgent alert: System maintenance scheduled.' }
        }).as('sendNotification');

        cy.request('POST', '/api/notifications/send', { type: 'urgent', message: 'Urgent alert: System maintenance scheduled.' });

        cy.wait('@sendNotification');

        cy.window().then((win) => {
            const notification = new win.Notification('Urgent alert: System maintenance scheduled.');
            expect(notification).to.exist;
            expect(notification.title).to.equal('Urgent alert: System maintenance scheduled.');
        });
    });

    it('should not display a push notification for non-urgent alerts', () => {
        cy.intercept('POST', '/api/notifications/send', {
            statusCode: 200,
            body: { message: 'Regular update: All systems operational.' }
        }).as('sendNotification');

        cy.request('POST', '/api/notifications/send', { type: 'regular', message: 'Regular update: All systems operational.' });

        cy.wait('@sendNotification');

        cy.window().then((win) => {
            const notification = new win.Notification('Regular update: All systems operational.');
            expect(notification).to.not.exist; // Expect no notification to be displayed
        });
    });
});
